                s("Key", "PMBOK 8 is your primary reference. It merges the ITTO detail of PMBOK 6 with the principle-and-domain structure of PMBOK 7, adding AI and sustainability themes.", SectionKind.KEY),
                s("PMBOK Evolution — What Changed", tableHeaders = listOf("PMBOK 6", "PMBOK 7 (2021)", "PMBOK 8 (2025) ⭐"), tableRows = listOf(listOf("Framework", "49 Processes + 10 Knowledge Areas", "12 Principles + 8 Performance Domains", "6 Principles + 7 Domains + 40 Processes"), listOf("Process Groups", "5 explicit groups", "Removed — not named", "Reintroduced as 5 Focus Areas"), listOf("ITTOs", "Fully detailed — central to the guide", "Removed", "Reintegrated into domain processes"), listOf("Lifecycle", "Predictive bias", "Agnostic", "Fully agnostic + AI + Sustainability | Exam: 40% Predictive / 60% Agile & Hybrid"), listOf("Quality", "Separate KA (Ch. 8)", "Part of Delivery domain", "Inside Governance domain"), listOf("Communications", "Separate KA (Ch. 10)", "Part of Stakeholders domain", "Merged into Stakeholders domain"), listOf("Procurement", "Separate KA (Ch. 12)", "Part of domains", "Across Resources + Governance"))),
                s("Why Was PMBOK 8 Created? — Evidence-Based", "PMI surveyed ~64,000 practitioners globally. Key findings that drove PMBOK 8:\n\n• 88% wanted principle-based standard — but principles should be more actionable and directly linked to domains\n• 80% wanted the 5 Process Groups (Focus Areas) reintroduced — universally useful regardless of development approach\n• 79% wanted technical processes (ITTOs) integrated back into the guide — not removed"),
                s("Why Was PMBOK 8 Created? — Evidence-Based", "Design rule: If a topic (e.g., stakeholder engagement) is already a performance domain, it should NOT also be a principle — avoid duplication. This is why PMBOK 8's 6 principles are broader and behavioural.", SectionKind.NOTE),
                s("The 6 Project Management Principles", "The 12 principles from PMBOK 7 are consolidated into 6 broader ones, organised around 3 mindset dimensions:"),
                s("The 6 Project Management Principles", tableHeaders = listOf("#", "Principle", "Mindset Dimension", "Core Meaning"), tableRows = listOf(listOf("1", "Adopt a Holistic View", "🔵 Proactive", "Think systemically — consider all interconnections, stakeholders, and broader context. Enables integrated decision-making and proactive risk management."), listOf("2", "Focus on Value", "🟠 Value-Driven", "Every activity must justify itself by the value it creates — tangible (revenue, savings) and intangible (satisfaction, reputation). Aligned to organisational strategy."), listOf("3", "Embed Quality Into Processes and Deliverables", "🔵 Proactive", "Build quality in from the start — not inspected in at the end. Continuous improvement and waste elimination. Dimensions: performance, conformity, reliability."), listOf("4", "Be an Accountable Leader", "🟢 Ownership", "Lead with integrity and responsible decisions. Leadership is SHARED — any team member or stakeholder can demonstrate leadership. Foster psychological safety."), listOf("5", "Integrate Sustainability Within All Project Areas", "🟠 Value-Driven", "Consider environmental, social, and economic impacts in all decisions. Triple bottom line: people, profit, planet. Broadens PM from compliance → achievement → sustainability."), listOf("6", "Build an Empowered Culture", "🟢 Ownership", "Create mutual trust, clear roles, and collaborative objectives. Empowered stakeholders contribute freely, maximise value delivery, and drive project success."))),
                s("The 7 Performance Domains", tableHeaders = listOf("Domain", "PMBOK 6 KAs Absorbed", "Focus Area"), tableRows = listOf(listOf("Governance", "Integration Management + Quality Management", "Framework, decisions, change control, quality assurance, knowledge management, value delivery"), listOf("Scope", "Scope Management", "Define, document, and control what is and is not included in the project"), listOf("Schedule", "Schedule Management", "Plan, develop, and control the project timeline and delivery cadence"), listOf("Finance", "Cost Management", "Financial planning, cost estimation, budgeting, EVM, benefits realisation"), listOf("Stakeholders", "Stakeholder Management + Communications Management", "Identify, engage, and communicate with all project stakeholders"), listOf("Resources", "Resource Management + Procurement Management", "Acquire, develop, and manage people and physical resources"), listOf("Risk", "Risk Management", "Identify, analyse, and respond to threats and opportunities continuously"))),
                s("The 7 Performance Domains", "Quality is in Governance. Communications is in Stakeholders. Procurement is in Resources + Governance. These mergers are important — questions may test where these now live.", SectionKind.WARN),
