                s("The 5 Focus Areas (Process Groups — Reintroduced)", tableHeaders = listOf("Focus Area", "Purpose", "Key Governance Processes"), tableRows = listOf(listOf("Initiating", "Authorise the project/phase; articulate desired end state; align priorities and constraints", "Initiate Project or Phase"), listOf("Planning", "Determine objectives, approach, and integrated PM plan across all 7 domains", "Integrate and Align Plans; Plan for all 7 domains"), listOf("Executing", "Complete work; drive execution to achieve value of the integrated baseline", "Manage Project Execution; Manage Quality Assurance; Acquire Resources; Lead Team; Implement Risk Responses"), listOf("Monitoring & Controlling", "Track, measure, regulate progress; identify variances; initiate corrective actions", "Monitor & Control Performance; Assess & Implement Changes — runs in PARALLEL with all other Focus Areas"), listOf("Closing", "Formally complete project/phase; transition to operations; lessons learned; verify benefits", "Close Project or Phase"))),
                s("The 5 Focus Areas (Process Groups — Reintroduced)", "Focus Areas are NOT phases — multiple can be active simultaneously. Monitoring & Controlling runs THROUGHOUT the entire project, in parallel with all others.", SectionKind.DANGER),
                s("Delivery Cadence Types (PMBOK 8)", tableHeaders = listOf("Cadence", "Description", "Example"), tableRows = listOf(listOf("Single", "All outcomes delivered at project end", "Process reengineering rollout"), listOf("Multiple", "Several components at different times — sequential or parallel", "Drug development: Phase 1 → 2 → 3 → regulatory approval"), listOf("Periodic", "Fixed schedule deliveries (sprint-based, monthly)", "Software: 2-week internal builds, monthly market releases"), listOf("Continuous", "Production-ready value via automation on an ongoing basis", "SaaS product with CI/CD pipeline"))),
                s("AI & Sustainability in PMBOK 8", "AI Integration\n • AI explicitly named as a PM enabler for the first time\n• AI supports real-time tracking, analysis, and reporting across all domains\n• Cloud computing and digital tools now part of EEF (project environment)\n• AI prompting formally listed as a communication skill\n• Continuous delivery and deployment enabled by automation\nSustainability\n • Triple bottom line: People, Profit, Planet\n• Three orientation levels: Compliance → Achievement → Sustainability\n• Sustainability goals should be in the business case (confirmed by sponsor)\n• Sustainability risks must be identified in the risk register\n• Applies to all 7 domains — schedule, finance, resources all have sustainability considerations"),
                s("Governance Domain — 8 Processes in Detail", tableHeaders = listOf("Process", "Focus Area", "What It Does", "Key Outputs"), tableRows = listOf(listOf("Initiate Project or Phase", "Initiating", "Authorise the project; define desired end state; align stakeholders", "Project Charter, Assumption Log, Stakeholder identification"), listOf("Integrate and Align Project Plans", "Planning", "Consolidate all subsidiary plans into one integrated baseline", "Project Management Plan, Integrated Baseline"), listOf("Plan Sourcing Strategy", "Planning", "Decide make-or-buy; select procurement approach", "Procurement Strategy, Make-or-Buy Decisions"), listOf("Manage Project Execution", "Executing", "Direct and coordinate all project work", "Deliverables, Work Performance Data, Change Requests"), listOf("Manage Quality Assurance", "Executing", "Ensure quality processes are followed; audits", "Quality Reports, Process improvements"), listOf("Manage Project Knowledge", "Executing", "Capture and share knowledge; lessons learned", "Lessons Learned Register, OPA updates"), listOf("Monitor and Control Project Performance", "M&C", "Track and compare actual vs planned; recommend corrective action", "Work Performance Reports, Change Requests"), listOf("Assess and Implement Changes", "M&C", "Evaluate all change requests; approve/reject via CCB", "Approved Changes, Change Log, Plan Updates"), listOf("Close Project or Phase", "Closing", "Formally complete; verify benefits; transition to operations", "Final Report, Lessons Learned, Closed Contracts"))),
