nt"), listOf("Project Schedule", "Gantt or other schedule format with dates and assignments", "Planning and updates", "Status reporting, team coordination"), listOf("Project Team Assignments", "People assigned to activities with roles", "Planning and Executing", "Schedule development, responsibility"), listOf("Quality Control Measurements", "Results of quality inspections and tests", "Control Quality process", "Manage Quality, defect analysis"), listOf("Quality Metrics", "Specific parameters to measure (e.g., defect density, test coverage)", "Planning — Quality Management Plan", "Control Quality process"), listOf("Quality Reports", "Summary of quality activities, issues, and improvements", "Manage Quality process", "Sponsor communication, audits"), listOf("Requirements Documentation", "All requirements with attributes and approval status", "Planning (Elicit Requirements)", "Scope definition, RTM"), listOf("Requirements Traceability Matrix", "Links requirements to WBS elements, test cases, deliverables", "Planning and when requirements change", "Validate Scope, change impact"), listOf("Resource Breakdown Structure", "Hierarchical chart of resources by category and type", "Planning", "Resource cost estimation"), listOf("Resource Calendars", "Availability of specific resources over the project timeline", "Planning and Executing", "Schedule development, resource levelling"), listOf("Resource Requirements", "Type and quantity of resources needed per activity", "Planning", "Resource acquisition, cost estimation"), listOf("Risk Register", "All identified risks with analysis, response plans, and owners", "Throughout project", "Risk monitoring, contingency planning"), listOf("Risk Report", "Summary of overall risk exposure and key individual risks", "Risk analysis processes", "Steering committee, executive communication"), listOf("Schedule Forecasts", "SPI, projected finish date, schedule variance", "M&C", "Sponsor reports, decision-making"), listOf("Stakeholder Register", "All stakeholders with their role, interest, influence, and engagement level", "Initiating, then updated continuously", "Stakeholder management, communication planning"), listOf("Team Charter", "Team norms, values, working agreements, communication preferences", "Forming stage (early executing)", "Conflict resolution reference, new member onboarding"))),
