                Chapter(
            "scope",
            "📐 Scope Management",
            "WBS · Requirements Types · Elicitation · Validate vs Control Scope",
            "Knowledge domains",
            listOf(
                s("Scope Terminology", tableHeaders = listOf("Term", "Definition", "Exam Trap"), tableRows = listOf(listOf("Product Scope", "Features and functions that characterise the product/service/result", "Different from Project Scope"), listOf("Project Scope", "Work required to deliver the product with specified features", "Includes product scope + all PM work"), listOf("Scope Creep", "Uncontrolled addition of features without change control — caused by poor requirements and weak change control", "Very common exam topic — always a problem"), listOf("Gold Plating", "Adding extras BEYOND agreed scope — even if well-intentioned", "Avoid! Wastes resources, introduces unreviewed risk, not what customer asked for"), listOf("Progressive Elaboration", "Continuously improving project plan detail as more info becomes available", "Same concept as Rolling Wave Planning"))),
                s("Requirements Classification (PMBOK 8 — Formalised)", tableHeaders = listOf("Type", "Description", "Example"), tableRows = listOf(listOf("Business", "High-level strategic needs; WHY the project exists", "Increase market share by 15%"), listOf("Stakeholder", "Needs of a specific stakeholder or group", "CFO needs monthly cost variance reports"), listOf("Functional", "What the product MUST DO — behaviours, actions, data", "System must allow password reset via email link"), listOf("Nonfunctional", "HOW the product performs — performance, security, reliability, usability", "System must support 10,000 concurrent users with <2 sec response time"), listOf("Transition", "Temporary capabilities to move from current to desired future state", "Data migration scripts; user training program; parallel run period"))),
                s("Requirements Classification (PMBOK 8 — Formalised)", "Requirements must be: Unambiguous, Measurable, Testable, Traceable, Complete, Consistent, and Acceptable to key stakeholders — BEFORE baselining.", SectionKind.TIP),
                s("WBS — Work Breakdown Structure", "• Definition: Hierarchical decomposition of total project scope into manageable work packages\n• 100% Rule: WBS must capture 100% of project scope — nothing more, nothing less\n• Work Package: Lowest-level WBS component — what gets estimated, scheduled, and assigned to a team\n• WBS Dictionary: Detailed description of each work package — owner, resources, duration, cost estimate, acceptance criteria\n• Planning Package: WBS component with known work content but not yet decomposed (used in rolling wave planning)\n• Scope Baseline = Project Scope Statement + WBS + WBS Dictionary (all three together)"),
                s("Validate Scope vs. Control Scope — Frequently Confused", "Validate Scope\n • Process of formalising ACCEPTANCE of completed deliverables\n• Done WITH the customer / sponsor / product owner\n• Input: Verified Deliverables (from Control Quality)\n• Output: Accepted Deliverables\n• Concerned with customer ACCEPTANCE\n• Performed in M&C Focus Area\nControl Scope\n • Process of monitoring scope status and managing changes to scope baseline\n• Done by the project team continuously\n• Input: Work Performance Data\n• Output: Work Performance Information, Change Requests\n• Concerned with PREVENTING scope creep\n• Performed continuously throughout the project"),
                s("Validate Scope vs. Control Scope — Frequently Confused", "Critical Sequence: Control Quality → Verified Deliverables → Validate Scope → Accepted Deliverables. Control Quality is ALWAYS performed BEFORE Validate Scope. This sequence is frequently tested.", SectionKind.DANGER),
                s("Requirements Traceability Matrix (RTM)", "• Links requirements from origin through to final deliverable — ensures nothing is missed\n• Traces: business need → business requirement → project requirement → design → test → delivery\n• Key exam point: If a requirement is not in the RTM, it is not in scope\n• Managed as part of Scope Management throughout the project lifecycle"),
                s("Requirements Elicitation Techniques", tableHeaders = listOf("Technique", "Description", "Best For"), tableRows = listOf(listOf("Interviews", "One-on-one or small group discussions to elicit requirements", "Detailed requirements from key stakeholders; sensitive topics"), listOf("Focus Groups", "Prequalified stakeholders and SMEs discuss expectations", "Understanding needs of a specific user group"), listOf("Facilitated Workshops", "Cross-functional stakeholders define requirements together (JAD sessions)", "Reconciling stakeholder differences; building consensus"), listOf("Brainstorming", "Generate ideas quickly without judgment", "Early-stage requirement discovery"), listOf("Nominal Group Technique", "Brainstorming + ranking/voting to prioritise", "Prioritising many ideas"), listOf("Delphi Technique", "Anonymous expert opinions gathered iteratively until consensus", "Avoiding groupthink; sensitive or political topics"), listOf("Observation (Job Shadowing)", "Watching users perform their work", "Discovering unstated requirements users cannot articulate"), listOf("Prototypes", "Working model of the expected product for early feedback", "Validating requirements when they are hard to describe"), listOf("Questionnaires / Surveys", "Written questions to large audience", "Many stakeholders; geographically dispersed; quantitative data"), listOf("Document Analysis", "Review existing documentation", "Regulatory requirements; existing system requirements"), listOf("Context Diagrams", "Visual model of system scope and interfaces", "Understanding system boundaries"), listOf("Benchmarking", "Compare practices to comparable organisations", "Identifying best practices"))),
                s("Prioritisation Techniques", tableHeaders = listOf("Technique", "How It Works", "Where Used"), tableRows = listOf(listOf("MoSCoW", "Must have / Should have / Could have / Won't have (this time)", "Agile backlogs; requirement prioritisation"), listOf("Kano Model", "Basic (expected) / Performance (more is better) / Excitement (delighters)", "Product feature prioritisation"), listOf("WSJF (Weighted Shortest Job First)", "Cost of Delay ÷ Job Size — highest score first", "SAFe; objective prioritisation"), listOf("Paired Comparison", "Compare each item against every other item", "Small sets of requirements"), listOf("100-Point Method", "Stakeholders distribute 100 points across requirements", "Stakeholder-driven prioritisation"), listOf("Multi-Criteria Decision Analysis", "Weighted scoring across multiple criteria", "Complex decisions with multiple factors"))),
                s("Scope in Agile vs. Predictive", tableHeaders = listOf("Aspect", "Predictive", "Agile"), tableRows = listOf(listOf("Scope definition", "Fully defined upfront in scope statement + WBS", "Emerges through backlog refinement; high-level vision upfront"), listOf("Scope baseline", "Fixed; changes via formal change control", "Product backlog is dynamic; PO reprioritises continuously"), listOf("Scope validation", "Formal acceptance at milestones", "Sprint review acceptance of increment"), listOf("Scope creep control", "Change control process; CCB", "Sprint Goal protection; only PO changes backlog"), listOf("Decomposition", "WBS → work packages", "Theme → Epic → Story → Task"), listOf("Requirements doc", "Requirements documentation + RTM", "User stories with acceptance criteria"))),
                s("Definition of Ready vs. Definition of Done", "Definition of Ready (DoR)\n • Criteria a backlog item must meet BEFORE it can be pulled into a sprint\n• Example: story is clear, estimated, acceptance criteria defined, dependencies resolved\n• Prevents teams from starting work on poorly understood items\n• Not an official Scrum artifact but widely used\nDefinition of Done (DoD)\n • Criteria an item must meet to be considered COMPLETE\n• Example: code reviewed, tested, documented, deployed to staging\n• Ensures consistent quality across all increments\n• Official Scrum artifact commitment for the Increment"),
                s("Worked example — Real-World Example: Scope Creep vs Gold Plating vs Legitimate Change", "Project: Customer-facing payments portal for a fintech startup\n\nScenario A — Scope Creep:\n\nThe customer casually mentions in a meeting: \"Oh, and can you add dark mode?\" The developer adds it over the weekend without a change request.\n\n→ This is SCOPE CREEP. Work was added without going through change control. Even if it takes only 4 hours — it sets a dangerous precedent, and now \"dark mode\" is in the product but not in any test plan, documentation, or baseline.\n\nScenario B — Gold Plating:\n\nThe developer decides to add animated micro-interactions to every button because \"it will delight users.\" The customer never asked for this.\n\n→ This is GOLD PLATING. The team is adding beyond agreed scope. It wastes time, adds untested features, and may not align with the customer's brand or performance requirements.\n\nScenario C — Legitimate Change:\n\nThe customer submits a written request for dark mode after seeing a competitor launch it. The PM raises a change request, assesses it (+3 days, +₹45,000), the CCB approves, and baselines are updated.\n\n→ This is the RIGHT way. Change is welcome — uncontrolled change is the problem.\n\nThe rule: Any addition to scope, however small, requires a change request. \"Small\" changes are where scope creep enters.", SectionKind.TIP),
                s("Worked example — WBS Creation — Step by Step Example", "Project: Launch a PMP® Exam Prep Online Course\n\nLevel 1 — Project: PMP Exam Prep Course Launch\n\nLevel 2 — Major Deliverables:\n\n1.0 Course Content\n\n2.0 Learning Management System (LMS)\n\n3.0 Marketing\n\n4.0 Project Management\n\nLevel 3 — Components:\n\n1.1 Study Notes (21 modules)\n\n1.2 Video Lectures (21 modules × 30 min)\n\n1.3 Practice Questions (500+)\n\n1.4 Mock Exams (3 × 180 questions)\n\n2.1 Platform selection and setup\n\n2.2 Content upload and QA\n\n2.3 Payment integration\n\n3.1 Landing page design\n\n3.2 SEO and content marketing\n\n3.3 LinkedIn/YouTube launch campaign\n\nLevel 4 — Work Packages (lowest level):\n\n1.1.1 Write PMBOK 8 module (owner: Sushant; est: 8h; cost: ₹8,000)\n\n1.1.2 Review and edit PMBOK 8 module (owner: Reviewer; est: 2h; cost: ₹2,000)\n\n100% Rule check: Does the WBS include everything in the scope statement? Does it include ONLY what is in the scope statement? If yes to both — the WBS passes.", SectionKind.TIP),
                s("Worked example — Requirements Elicitation — Choosing the Right Technique", "Situation 1: You are gathering requirements for a new core banking system that will be used by 2,000 branch staff across India. Most cannot be interviewed individually.\n\n→ Best technique: Survey/Questionnaire — reach large, dispersed audience efficiently. Follow up with Focus Groups in 3–4 regional hubs for depth.\n\nSituation 2: The CFO and CTO disagree on what \"real-time reconciliation\" means for the system.\n\n→ Best technique: Facilitated Workshop (JAD session) — bring both together with a neutral facilitator to define the term with measurable acceptance criteria. Ground rules: no hierarchy in the room, decisions documented immediately.\n\nSituation 3: Branch tellers say the current system is \"fine\" but complaints data shows 40% of errors happen during account opening. They cannot articulate what goes wrong.\n\n→ Best technique: Observation (Job Shadowing) — watch tellers open accounts in real time. You will see the unstated workflow steps, workarounds, and friction points they cannot describe in a meeting.\n\nSituation 4: You need to know if customers would prefer mobile biometric authentication, OTP, or PIN for transaction confirmation. 15,000 users need to be sampled.\n\n→ Best technique: Survey/Questionnaire + Data Analysis — quantitative data from a large sample, then prototype-test the top choice with a Focus Group.\n\nRemember: The BEST technique depends on WHO you need to reach, HOW many, and WHAT type of requirement (explicit vs implicit vs unstated).", SectionKind.TIP),
                s("Requirements Types — Comprehensive Classification", tableHeaders = listOf("Type", "Definition", "Example (Banking Project)", "Elicitation Approach"), tableRows = listOf(listOf("Business Requirements", "Why the organisation is undertaking the project — the business need", "Reduce loan processing time from 8 days to same-day to compete with digital-first banks", "Executive workshops, business case analysis"), listOf("Stakeholder Requirements", "What specific stakeholders need from the project", "Loan officers need to view customer credit history without switching to another system", "Interviews, observation, focus groups"), listOf("Solution Requirements — Functional", "What the system must DO", "The system must allow customers to upload KYC documents and receive auto-classification within 5 minutes", "Workshops, user stories, use cases"), listOf("Solution Requirements — Non-Functional", "How the system must PERFORM", "System response time <2 seconds for 95th percentile; 99.9% availability; TLS 1.3 encryption", "Performance testing specs, SLA review"), listOf("Transition Requirements", "What must happen to move from current to future state", "All existing loan files must be migrated to the new system before go-live; training for 200 loan officers must be completed 2 weeks before launch", "Process analysis, data migration study"), listOf("Project Requirements", "Actions, processes, or conditions the project itself must meet", "Weekly status report submitted by Monday 9 AM; all vendors must have ISO 27001 certification", "PMO standards, governance framework"), listOf("Quality Requirements", "Criteria the deliverable must meet to satisfy stakeholders", "Zero critical defects at go-live; User Acceptance Testing pass rate ≥95%", "Quality management plan, acceptance criteria workshop"), listOf("Compliance Requirements", "Regulatory or legal requirements the deliverable must satisfy", "RBI compliance for digital lending; DPDP Act 2023 data privacy requirements", "Legal and compliance review, regulatory analysis"))),
                s("WBS Construction Rules — Every Rule Tested", tableHeaders = listOf("Rule", "Explanation", "Example of Violation", "Correct Approach"), tableRows = listOf(listOf("100% Rule", "WBS must capture 100% of work — no more, no less", "WBS includes \"Marketing\" but marketing is not in scope. Or WBS misses \"User Training\" which is in scope.", "Review scope statement and WBS together — every scope element must have a WBS element and vice versa"), listOf("Mutually Exclusive", "No overlap between WBS elements at the same level", "\"Mobile App Development\" and \"iOS App Development\" at the same level — iOS is a subset of Mobile", "Ensure clean decomposition: parent → children with no overlap"), listOf("Outcome-Oriented", "WBS elements are deliverables (nouns), not activities (verbs)", "WBS element: \"Conduct User Training\" (activity)", "WBS element should be: \"Trained Users\" or \"Training Programme\" — the deliverable"), listOf("Work Package Level", "Decompose until work is manageable (can be estimated, assigned, and controlled)", "Work package: \"Complete software development\" (too vague)", "Work package: \"User authentication module — development and unit test\" (specific and estimable)"), listOf("8/80 Rule (guideline)", "Work packages should be 8–80 hours of effort (rough guideline, not a rule)", "Work package is 600 hours — too large to control", "Break into smaller packages; or use rolling wave planning for future phases"), listOf("No orphan work", "All actual work must trace to a WBS element", "A developer works on error logging that is not in the WBS", "Any work performed should be added to WBS via a change request if it is in scope"), listOf("WBS ≠ OBS", "WBS is about deliverables; Org Breakdown Structure (OBS) is about responsibility. They intersect at control accounts.", "Using the org chart to build the WBS (by department)", "Build WBS from scope statement (deliverables), then assign responsibility via OBS"))),
                s("Validate Scope vs Control Scope — The Most Tested Distinction", tableHeaders = listOf("Aspect", "Validate Scope", "Control Scope"), tableRows = listOf(listOf("Purpose", "Gain formal acceptance of deliverables from the customer/sponsor", "Monitor project and product scope; manage changes to scope baseline"), listOf("When", "Monitoring & Controlling — when a deliverable is complete", "Monitoring & Controlling — continuously throughout the project"), listOf("Who", "Customer or authorised stakeholder (external focus)", "PM and team (internal focus)"), listOf("Key Input", "Verified Deliverables (from Control Quality)", "Work Performance Data + Project Management Plan"), listOf("Key Output", "Accepted Deliverables (fed into Close Project)", "Work Performance Information, Change Requests"), listOf("What happens if it fails", "Deliverable returned for rework; remains \"Verified\" but not \"Accepted\"", "Change request raised to address scope deviation"), listOf("Relationship", "Control Quality comes FIRST → Verified Deliverables → Validate Scope → Accepted Deliverables", "Parallel to Validate Scope; monitoring for scope creep, gold plating, or unauthorized changes"), listOf("Focus", "Correctness from the CUSTOMER's perspective", "Correctness relative to the BASELINE"), listOf("Exam trap", "\"Customer inspects deliverable\" = Validate Scope. \"Team inspects deliverable against spec\" = Control Quality", "Scope Baseline change requires CCB approval through Control Scope. Customer request alone is not enough."))),
                s("Requirements Elicitation — All Techniques with Selection Guide", tableHeaders = listOf("Technique", "Description", "Best Used When", "Limitation"), tableRows = listOf(listOf("Interviews", "One-on-one or small group structured or unstructured conversation", "SMEs with unique knowledge; senior executives; sensitive topics; need deep insight", "Time-intensive; hard to scale beyond 15–20 people; interviewer bias"), listOf("Focus Groups", "Moderated discussion with pre-qualified stakeholders (typically 6–12)", "Exploring attitudes, perceptions, or reactions to a concept or prototype", "Group dynamics can suppress minority opinions; needs skilled facilitator"), listOf("Facilitated Workshops (JAD/RAD)", "Structured group sessions with all key stakeholders together", "Aligning cross-functional requirements quickly; resolving conflicting requirements", "Requires scheduling all stakeholders; powerful participants can dominate"), listOf("Surveys/Questionnaires", "Structured written questions distributed to a large group", "Large, dispersed population; quantitative data needed; preliminary screening", "No opportunity for clarification; response rate may be low; surface-level only"), listOf("Observations (Job Shadowing)", "Watch users perform their actual work in their actual environment", "Processes users cannot articulate; discovering unstated requirements; process improvement", "Time-consuming; observer effect; requires access to workplace"), listOf("Prototypes", "Create a preliminary model of the expected product for stakeholder feedback", "Novel product concepts; UI/UX requirements; requirements too abstract to discuss verbally", "Can anchor stakeholders to prototype features; scope creep risk; takes time to build"), listOf("Benchmarking", "Compare processes, products, or practices against industry leaders or competitors", "Understanding market standards; setting quality targets; justifying requirements", "Information may not be available; industry may differ significantly from your context"), listOf("Context Diagrams", "Visual diagram showing the system in context with all external entities that interact with it", "Understanding system boundaries; identifying all external interfaces and actors", "High-level only; does not reveal internal requirements"), listOf("Document Analysis", "Review existing documentation — SOPs, contracts, incident logs, legal requirements", "Discovering implicit requirements; understanding existing system constraints; regulatory compliance", "Documentation may be outdated or incomplete; time-intensive review"), listOf("Brainstorming", "Group idea generation without judgment", "Early requirements exploration; generating a wide list of potential requirements", "Quantity over quality; dominant personalities may skew results; needs follow-up structure"), listOf("Mind Mapping", "Visual hierarchical diagram of related concepts branching from a central theme", "Organising requirements by category; making connections visible; group elicitation sessions", "May miss requirements that don't fit the tree structure"), listOf("Nominal Group Technique", "Silent individual idea generation followed by group ranking — prevents group-think", "Prioritising requirements when opinions diverge; ensuring quiet stakeholders contribute", "Loses contextual discussion; ranking may not capture nuance"))),
                s("Scope Baseline vs Scope Statement — Know the Difference", tableHeaders = listOf("Element", "What It Is", "Format", "Example Content"), tableRows = listOf(listOf("Project Scope Statement", "Narrative description of what is and is not in scope — the \"boundary document\"", "Prose document with specific sections", "IN scope: Mobile banking app for iOS and Android. OUT of scope: Web browser version, back-office admin system, ATM integration."), listOf("WBS", "Hierarchical decomposition of total scope into manageable components", "Tree diagram or outline structure", "1.0 Mobile Banking App → 1.1 Authentication → 1.1.1 Biometric login module → 1.1.2 PIN fallback module"), listOf("WBS Dictionary", "Detailed description of each WBS element — the \"scope specification\"", "Table or structured document per WBS element", "1.1.1 Biometric Login Module: description, acceptance criteria, responsible party, estimated effort, dependencies, quality standards"), listOf("Scope Baseline", "The APPROVED combination of all three above — the official record of agreed scope", "All three documents together, stamped \"Approved\"", "The baseline against which Control Scope measures any deviation. Changes require CCB approval."))),
            )
