            listOf(
                s("Stakeholder Engagement Levels", tableHeaders = listOf("Level", "Description", "PM Goal", "Engagement Strategy"), tableRows = listOf(listOf("Unaware", "Not aware of the project or its potential impacts", "Move to Supportive or higher", "Proactive information sharing; education about project benefits and impacts"), listOf("Resistant", "Aware but OPPOSED — will not support the project or its outcomes", "Move to Neutral or higher", "Understand root concerns; engage in dialogue; address specific objections; involve in decisions"), listOf("Neutral", "Aware but neither supportive nor opposed — passive stance", "Move to Supportive", "Clarify benefits and value; involve in planning to build ownership and investment"), listOf("Supportive", "Aware and supportive — will support but not actively champion", "Maintain; leverage", "Maintain regular communication; leverage their support; keep them engaged"), listOf("Leading", "Actively CHAMPIONING the project — highly engaged advocate", "Maintain; empower", "Empower and enable their advocacy; use as change agents; co-create solutions"))),
                s("Stakeholder Engagement Levels", "The Stakeholder Engagement Assessment Matrix shows Current (C) vs Desired (D) level for each stakeholder. The GAP between C and D determines how much engagement effort is needed.", SectionKind.NOTE),
                s("Stakeholder Analysis Tools", "• Power/Interest Grid: High power + High interest = Manage Closely. High power + Low interest = Keep Satisfied. Low power + High interest = Keep Informed. Low power + Low interest = Monitor.\n• Stakeholder Register: Documents identification, assessment, classification — interests, involvement, interdependencies, influence, potential impact on project success\n• Stakeholder Engagement Assessment Matrix: C = current engagement level; D = desired engagement level. Gap requires targeted engagement activities.\n• Stakeholder responsibility: Assign only ONE responsibility at a time — wait for prior deadline before adding another. Prevents overload and maintains accountability."),
                s("Communication Methods", tableHeaders = listOf("Method", "Direction", "Best For", "Examples"), tableRows = listOf(listOf("Interactive", "Two-way, real-time — MOST EFFECTIVE for understanding", "Conflict resolution, sensitive topics, complex negotiations, problem-solving", "Meetings, phone calls, video conferences"), listOf("Push", "One-way; sender distributes to recipients; no confirmation of understanding", "Status updates, routine information, announcements", "Email, reports, memos, press releases, newsletters"), listOf("Pull", "Recipients access on demand when they need it", "Large audiences, reference material, optional information", "Intranets, SharePoint, knowledge bases, portals"))),
                s("Communication Methods", "Communication Channels"),
                s("Communications Management Plan — Must Know Contents", "• Who needs what information, from whom, in what format, with what frequency\n• Methods and technology used for each type of communication and each stakeholder group\n• Frequency and timing schedules for regular communications\n• Escalation path and timeframes for unresolved issues\n• Glossary of common terminology to ensure shared understanding\n• Constraints affecting communications (confidentiality, legal, regulatory, cultural)\n• Communication flow diagrams showing who communicates with whom"),
                s("Communication Skills — PMBOK 8 Three Dimensions", tableHeaders = listOf("Dimension", "Skills", "PMBOK 8 Notable Addition"), tableRows = listOf(listOf("Oral", "Active listening, presentation, questioning, meeting facilitation, interaction", "Active listening is key — PM spends 90% of time communicating"), listOf("Visual", "Data visualisation, dashboards, nonverbal communication, body language", "Nonverbal cues often communicate more than words"), listOf("Electronic", "Professional writing, email, texting, chatting, collaborative tools", "AI prompting formally listed as an electronic communication skill in PMBOK 8"))),
                s("Handling Stakeholder Issues", tableHeaders = listOf("Situation", "Correct PM Action"), tableRows = listOf(listOf("Stakeholder raises concerns about a missed requirement", "Review the established acceptance criteria and guide them through it — do not dismiss"), listOf("Complaints about communication or status reports", "Re-evaluate the communications plan and stakeholder engagement plan"), listOf("Stakeholder wants more project progress detail", "Encourage attendance at sprint reviews or demos; adjust communications frequency/format"), listOf("External threats beyond PM authority", "Escalate to the project sponsor — this is when escalation is appropriate"), listOf("Stakeholder conflict over project priorities", "Facilitate a collaborative discussion; use Power/Interest grid to inform approach"))),
                s("Power/Interest Grid — Full Strategy", tableHeaders = listOf("Quadrant", "Power", "Interest", "Strategy", "Example"), tableRows = listOf(listOf("Manage Closely", "High", "High", "Engage fully; involve in decisions; frequent communication", "Sponsor, key customer"), listOf("Keep Satisfied", "High", "Low", "Meet their needs; do not overwhelm with detail; escalation path", "Executive not directly involved; regulator"), listOf("Keep Informed", "Low", "High", "Regular updates; leverage as advocates", "End users, team members"), listOf("Monitor", "Low", "Low", "Minimal effort; watch for changes in position", "Peripheral departments"))),
                s("Other Stakeholder Models", tableHeaders = listOf("Model", "Dimensions", "Use"), tableRows = listOf(listOf("Power/Influence Grid", "Power (authority) vs Influence (active involvement)", "When influence differs from formal power"), listOf("Impact/Influence Grid", "Impact (ability to change plans) vs Influence", "Assessing who can change project direction"), listOf("Salience Model", "Power, Urgency, Legitimacy (3 circles)", "Complex stakeholder environments; identifies \"definitive\" stakeholders (all 3)"), listOf("Stakeholder Cube", "3D combination of grids", "Very complex projects"), listOf("Direction of Influence", "Upward (senior), Downward (team), Outward (external), Sideward (peers)", "Understanding influence relationships"))),
                s("Communication Models", tableHeaders = listOf("Model", "Components", "Key Insight"), tableRows = listOf(listOf("Basic Sender-Receiver", "Encode → Transmit → Decode → Acknowledge → Feedback", "Noise can disrupt any step; feedback confirms understanding"), listOf("Interactive Model", "Adds acknowledgement and feedback loops", "Communication is bidirectional; ensure message received"), listOf("Cross-Cultural Model", "Sender and receiver have different frames of reference", "Cultural context affects encoding and decoding"))),
                s("Communication Models", "Exam point: The SENDER is responsible for clear encoding and confirming the message was understood. The RECEIVER is responsible for decoding and acknowledging. Both share responsibility for effective communication.", SectionKind.KEY),
                s("Communication Types", tableHeaders = listOf("Dimension", "Options"), tableRows = listOf(listOf("Formal vs Informal", "Formal: reports, briefings, contracts. Informal: emails, conversations, social media"), listOf("Internal vs External", "Internal: within project/org. External: customers, vendors, public, regulators"), listOf("Vertical vs Horizontal", "Vertical: up/down the hierarchy. Horizontal: with peers"), listOf("Official vs Unofficial", "Official: annual reports, regulatory filings. Unofficial: off-the-record"), listOf("Written vs Oral", "Written: permanent, precise. Oral: immediate, nuanced"), listOf("Verbal vs Nonverbal", "Verbal: words. Nonverbal: body language, tone (55% body language, 38% tone, 7% words per Mehrabian)"))),
                s("Meeting Management Best Practices", "• Set a clear agenda and distribute it in advance\n• Define the purpose: decision, information sharing, problem-solving, or status\n• Timebox the meeting; start and end on time\n• Assign a facilitator, note-taker, and timekeeper\n• Document decisions, action items (with owners and due dates), and follow-ups\n• Distribute meeting minutes promptly\n• Do not hold a meeting when an email would suffice\n• Agile: Daily Scrum is 15 min max; Sprint Review ≤4h; Retrospective ≤3h (for 4-week sprint)"),
                s("Stakeholder Engagement in Agile", tableHeaders = listOf("Practice", "Stakeholder Involvement"), tableRows = listOf(listOf("Product Owner", "Single voice of the customer; represents all stakeholders to the team"), listOf("Sprint Review", "Stakeholders see working increment; give direct feedback"), listOf("Backlog Refinement", "Stakeholders contribute to backlog items via PO"), listOf("Information Radiators", "Big visible charts (burndown, Kanban board) keep stakeholders informed without meetings"), listOf("Customer Collaboration", "Manifesto value: customer collaboration over contract negotiation"))),
                s("Worked example — Power/Interest Grid — Real Project Mapping", "Project: Digital Loan Origination System at a large bank\n\nManage Closely (High Power, High Interest):\n\n• CTO — Technology owner; approves infrastructure budget\n\n• Head of Retail Banking — Primary beneficiary; KPIs depend on faster loan processing\n\n• Project Sponsor (CMO) — Strategic champion\n\n→ Action: Weekly one-on-ones; include in all major decisions; address concerns before they escalate\n\nKeep Satisfied (High Power, Low Interest):\n\n• CFO — Has budget approval authority but delegates to sponsor\n\n• Risk & Compliance Head — High authority to stop the project if compliance gaps found\n\n→ Action: Monthly briefings; proactively share compliance status; never surprise them\n\nKeep Informed (Low Power, High Interest):\n\n• Branch Managers — Will use the system daily; highly invested in usability\n\n• Loan Officers (80 people) — Direct end users; need training and change management\n\n→ Action: Monthly newsletters; involve in UAT; training plan 6 weeks before go-live\n\nMonitor (Low Power, Low Interest):\n\n• IT Helpdesk — Will support the system but not engaged in development\n\n• External auditors — Will review post-go-live, not involved now\n\n→ Action: Standard communication only; notify of major decisions", SectionKind.TIP),
                s("Worked example — Communication Channels — Why This Formula Matters", "Why does communication complexity matter on real projects?\n\nSmall team (5 people): 5×4/2 = 10 channels. A PM can personally manage all relationships. Daily standup covers all coordination needs.\n\nMedium team (15 people): 15×14/2 = 105 channels. The PM cannot personally manage 105 relationships. Communication breaks down, assumptions form, decisions are made in silos. Need: team lead structure, documented decisions, clear escalation paths.\n\nLarge project (50 stakeholders): 50×49/2 = 1,225 channels. Without a formal Communications Management Plan, the project will drown in emails, conflicting information, and missed stakeholders.\n\nReal impact: Research shows 56% of project budget risk comes from poor communication (PMI Pulse of the Profession). The channel formula makes this concrete — it is not a theoretical formula, it is a communication complexity warning system.\n\nExam trap: \"Adding 3 people to a 12-person team creates how many NEW channels?\"\n\nBefore: 12×11/2 = 66. After: 15×14/2 = 105. New channels = 105−66 = 39 new channels.\n\nNot 3. Not 36. 39. The complexity grows non-linearly.", SectionKind.TIP),
                s("Worked example — Stakeholder Engagement Assessment Matrix — Working Example", "Project: Replacing legacy HR system with SAP SuccessFactors\n\n | Stakeholder | Role | Current | Desired | Gap | Engagement Plan\n\n | CHRO | Sponsor | Leading | Leading | None ✅ | Maintain; leverage as change champion\n\n | IT Director | Infra owner | Resistant | Supportive | Large ❌ | Understand concerns (integration complexity?); involve in architecture decisions; address technical worries directly\n\n | HR Managers (12) | Power users | Neutral | Supportive | Moderate | Involve in UAT; run demo sessions; address \"will this make my job harder?\" fears\n\n | CFO | Budget approver | Unaware | Neutral | Moderate | One briefing on project purpose and ROI; quarterly cost update\n\n | Employees (800) | End users | Unaware | Supportive | Large | Change management campaign: \"what's in it for me?\"; training program; FAQ intranet page\n\nPriority: IT Director (Resistant→Supportive) is the highest risk — has both the power and the motivation to create obstacles. Address first.", SectionKind.TIP),
                s("Stakeholder Identification — Comprehensive Sources", tableHeaders = listOf("Source", "Types of Stakeholders Found", "Exam Application"), tableRows = listOf(listOf("Project Charter", "Sponsor (named), initial customer, high-level approvers, funding entities", "Charter is the first source — whoever signed it is a key stakeholder"), listOf("Procurement Documents", "Vendors, contractors, subcontractors, bidders", "Anyone in the procurement chain has interests that can affect the project"), listOf("Organisational Charts", "Functional managers, department heads, executives whose teams are affected", "Especially important in matrix organisations where resources are shared"), listOf("Industry Contacts & SMEs", "Professional associations, standards bodies, technical experts", "Regulatory and industry standards bodies are often overlooked stakeholders"), listOf("Government and Regulatory Bodies", "Regulators, government agencies, compliance bodies, auditors", "Mandatory stakeholders on any regulated project — non-engagement = compliance risk"), listOf("Community and Public", "Local residents, NGOs, media, general public (for public projects)", "Infrastructure and environmental projects often have community stakeholders"), listOf("End Users", "People who will use the final product or system", "Often underrepresented in planning; critical for adoption success"), listOf("Project Team Members", "Developers, designers, testers, analysts", "Team members are stakeholders too — their needs and interests affect team performance"), listOf("Competitors", "Market competitors who may be affected by or react to the project outcome", "Relevant for commercial projects — a competitor's reaction is a business risk"), listOf("Previous Project Records (OPAs)", "Stakeholders from similar past projects who may be relevant again", "Lessons learned from past projects often include stakeholder blind spots"))),
                s("Stakeholder Identification — Comprehensive Sources", "Stakeholder identification is ONGOING — new stakeholders can emerge at any phase. The Identify Stakeholders process runs in Initiating BUT is revisited whenever the project context changes significantly (new phase, major change, environmental shift).", SectionKind.KEY),
                s("Stakeholder Register — Complete Field Reference", tableHeaders = listOf("Field", "Content", "Example"), tableRows = listOf(listOf("Identification", "Name, organisation, role, contact details", "Priya Sharma, Head of Digital Banking, pshrama@bank.com"), listOf("Assessment Information", "Major requirements and expectations; potential influence; most relevant phase", "Expects daily mobile banking metrics; High influence over go-live decision; Critical during UAT"), listOf("Stakeholder Classification", "Internal/External; Supporter/Neutral/Resistor; Power/Interest/Influence ratings", "Internal; Currently Neutral → target: Supportive; Power: High; Interest: Medium"), listOf("Current Engagement Level", "Unaware/Resistant/Neutral/Supportive/Leading", "Current: Unaware"), listOf("Desired Engagement Level", "What level is needed for project success", "Desired: Supportive"), listOf("Gap Analysis", "Current vs Desired — drives the engagement plan", "Gap: 2 levels. Need targeted briefing and involvement in UAT."), listOf("Engagement Strategy", "Specific planned actions to close the gap", "Monthly 1:1 briefings; Demo invitation Sprint 4; UAT participant; Recognition in launch communications"))),
                s("Worked example — Communication Planning Matrix — How to Build One", "Project: New digital lending platform for a bank\n\n | Stakeholder\n | Information Need\n | Format\n | Frequency\n | Method\n | Sender\n\n | Sponsor (CMO) | RAG status, risks, decisions needed | 1-page dashboard | Monthly | Face-to-face meeting | PM\n\n | Steering Committee | Phase progress, budget, strategic alignment | Presentation deck | Quarterly | Meeting | PM + Sponsor\n\n | IT Director | Technical status, infra needs, security issues | Technical report | Bi-weekly | Email + meeting | Tech Lead\n\n | Loan Officers (200) | What is changing, training timeline | Newsletter + FAQ | Monthly | Email (Push) | Change Manager\n\n | Project Team | Sprint goals, blockers, decisions | Standup + Kanban | Daily | In-person/Video | Scrum Master\n\n | RBI (Regulator) | Compliance milestones, audit readiness | Formal report | As required | Written submission | Compliance Officer\n\n | Vendor (Finacle) | Delivery milestones, change requests, issues | Status meeting + log | Weekly | Video + email | PM", SectionKind.TIP),
                s("Handling Difficult Stakeholder Situations", tableHeaders = listOf("Situation", "Root Cause", "Wrong Response", "Right Response"), tableRows = listOf(listOf("Stakeholder keeps adding new requirements after scope baseline is approved", "No real understanding of change control; thinks PM is the obstacle", "Informally add the requirements to avoid conflict", "Educate on the change control process; raise formal change request; quantify impact; CCB decides"), listOf("Executive stakeholder goes directly to team members with instructions", "Doesn't trust the PM or process; wants to \"help\" their team", "Tell team to ignore the executive", "Professional conversation with the executive; explain the impact on team clarity and schedule; agree on a communication protocol"), listOf("Stakeholder who was identified as \"Monitor\" suddenly becomes critical due to regulatory change", "Stakeholder landscape changed — identification is not static", "Continue treating them as low priority", "Re-classify in stakeholder register; update engagement plan; immediately initiate engagement strategy appropriate to new priority level"), listOf("Resistant stakeholder who has veto power over go-live", "Fear of failure; loss of control; previous bad experience; political threat", "Go around them or steamroll them", "Understand their specific concerns; involve them in decisions; address concerns with data; build trust incrementally; use the sponsor as a bridge if needed"), listOf("Stakeholder provides conflicting requirements from another stakeholder", "Each stakeholder represents different business interests", "Pick whichever you prefer", "Facilitated requirements workshop with BOTH stakeholders; use project objectives as the tiebreaker; escalate unresolvable conflicts to sponsor"), listOf("Stakeholder stops responding to communications", "Disengaged; busy; communication method is wrong for them", "Escalate immediately", "Try different communication channel and time; brief face-to-face; understand their preferred format; if truly critical, engage sponsor to help re-engage"))),
            )
        ),
                Chapter(
            "procurement",
            "📄 Procurement Management (Resources + Governance)",
            "Contract Types · PTA · Bidder Conference · Claims · Agile Procurement",
            "Knowledge domains",
            listOf(
                s("Contract Types — Risk Allocation", "The more DEFINED the scope, the more you can push risk to the SELLER. The more UNCERTAIN the scope, the more risk the BUYER must carry.", SectionKind.KEY),
                s("Contract Types — Risk Allocation", tableHeaders = listOf("Contract Type", "Risk: Buyer", "Risk: Seller", "When to Use", "Key Feature"), tableRows = listOf(listOf("FFP (Firm Fixed Price)", "Low ✅", "High ❌", "Well-defined scope; stable requirements; seller expertise known", "Price is fixed regardless of seller's actual costs"), listOf("FPIF (Fixed Price Incentive Fee)", "Low-Medium", "Medium", "Defined scope; want to incentivise performance efficiency", "Seller shares savings/overruns up to a ceiling price"), listOf("FPEPA (Fixed Price Economic Price Adjustment)", "Low-Medium", "Medium", "Long-term contracts; economic fluctuations expected (inflation)", "Pre-defined price adjustment formulas for economic changes"), listOf("CPFF (Cost Plus Fixed Fee)", "High ❌", "Low ✅", "Uncertain scope; R&D; when seller expertise critical", "Seller reimbursed ALL costs + fixed fee regardless of outcome"), listOf("CPIF (Cost Plus Incentive Fee)", "High", "Low-Medium", "Long projects; want to incentivise cost efficiency", "Seller shares in savings below target cost"), listOf("CPAF (Cost Plus Award Fee)", "High", "Low", "Subjective performance criteria; hard to define deliverables", "Buyer evaluates performance and awards fee subjectively"), listOf("T&M (Time and Material)", "Medium", "Medium", "Unclear scope; staff augmentation; short-term work", "Hybrid: pay for time + materials used; buyer controls hours"))),
                s("Point of Total Assumption (PTA) — FPIF Contracts Only", "Point of Total Assumption"),
                s("Procurement Documents", tableHeaders = listOf("Document", "Used When", "Purpose"), tableRows = listOf(listOf("RFP (Request for Proposal)", "Complex requirements; need vendor solution approach", "Request technical approach + price + qualifications"), listOf("RFQ (Request for Quotation)", "Clear specifications; price is primary decision factor", "Request price quotes for defined products/services"), listOf("IFB (Invitation for Bid)", "Well-defined scope; selecting on price only", "Formal bid process; lowest compliant bid wins"), listOf("SOW (Statement of Work)", "Part of contract package", "Describes what the seller must deliver in detail"))),
                s("Vendor Management Best Practices", "• Always review the Procurement Management Plan and contract/agreement FIRST before taking action\n• Communicate face-to-face or by phone to resolve vendor issues — do not rely solely on email\n• Evaluate alternatives before considering contract cancellation\n• Vendor delivery delays or quality issues → meet with vendor AND team to brainstorm solutions\n• In the event of a formal claim → escalate to Claims Administration — do not try to resolve legally yourself\n• Conduct regular milestone status reviews and walkthroughs to ensure contractor is on track\n• Make-or-buy analysis: gather data on requirements → analyse internal vs external options → formal decision"),
                s("Make-or-Buy Analysis", "• Make: Build internally — use when: unique capability needed, confidentiality required, idle capacity exists, lower long-term cost\n• Buy: Outsource/procure — use when: specialised expertise needed, faster delivery required, lower risk, not core competency\n• Analysis should consider: total cost, risk, quality, capacity, strategic fit, and delivery timeline\n• PMBOK 8: Make-or-buy analysis explicitly listed as a tool in both Resources and Governance domains"),
                s("Procurement Process Flow", "Plan Procurement→Prepare Bid Documents→Solicit Sellers→Evaluate Proposals→Select Seller→Award Contract→Administer Contract→Close Procurement"),
                s("Seller Selection Criteria", tableHeaders = listOf("Criterion", "Description"), tableRows = listOf(listOf("Technical Capability", "Does the seller have the skills and technology?"), listOf("Management Approach", "How will they manage the work?"), listOf("Financial Capacity", "Can they afford to deliver? Are they financially stable?"), listOf("Past Performance", "References, track record, similar projects"), listOf("Price / Total Cost", "Not just bid price — total cost of ownership"), listOf("Risk", "Seller-specific risks (single source, geopolitical, IP)"), listOf("Sustainability", "PMBOK 8: seller's environmental and social practices"))),
                s("Bidder Conferences", "• Meeting with ALL prospective sellers BEFORE bid submission\n• Purpose: ensure all sellers have a common, clear understanding of requirements\n• All questions and answers shared with ALL bidders — no private information\n• Ensures fairness (PMI Code of Ethics — Fairness value)\n• Also called: contractor conferences, vendor conferences, pre-bid conferences"),
                s("Contract Elements — What Makes a Valid Contract", tableHeaders = listOf("Element", "Description"), tableRows = listOf(listOf("Offer", "One party proposes terms"), listOf("Acceptance", "Other party agrees to those terms"), listOf("Consideration", "Something of value exchanged (money, services)"), listOf("Legal Capacity", "Both parties legally able to enter contract"), listOf("Legal Purpose", "Contract must be for a lawful purpose"))),
                s("Contract Change Control", "• All contract changes go through the CONTRACT change control system (defined in the contract)\n• Contract changes are more formal than internal project changes — legally binding\n• Constructive change: when the buyer directs work not in the contract without formal change → seller can claim\n• Claims: disagreements about compensation or terms → resolve through Claims Administration → mediation → arbitration → litigation\n• PM should aim to resolve claims through negotiation first (collaborative approach)"),
                s("Procurement in Agile", tableHeaders = listOf("Aspect", "Agile Approach"), tableRows = listOf(listOf("Contract Type", "T&M or cost-reimbursable preferred — scope evolves"), listOf("Master Agreement", "Master Services Agreement (MSA) + statement of work per sprint or release"), listOf("Scope Flexibility", "Fixed price per sprint with variable scope; or \"not-to-exceed\" with early termination option"), listOf("Collaboration", "Vendor team members may work as part of the Scrum team"), listOf("Incremental Delivery", "Payment tied to delivered increments, not milestones"))),
                s("Worked example — 📖 Worked Example: Choosing the Right Contract Type", "Project: A fintech startup needs a mobile payments SDK. Three possible scenarios:\n\nScenario A — Requirements are crystal clear:\n\nThe startup needs an off-the-shelf Aadhaar eKYC API integration. The spec is fully defined, the vendor has done it 50 times, and pricing is standard.\n\n→ Use Firm Fixed Price (FFP). Scope is defined, risk to seller is low, price is fair. Buyer's cost is locked. No surprises.\n\nScenario B — Requirements will evolve:\n\nThe startup wants a custom AI fraud detection engine. The exact features depend on what the ML models reveal during development. Nobody knows the final scope.\n\n→ Use Cost Plus Fixed Fee (CPFF) or T&M with a cap. Forcing a fixed price here means the vendor either overcharges (big contingency) or cuts corners. Pay actual costs + a fixed fee.\n\nScenario C — Defined scope, want to motivate the vendor to be efficient:\n\nA core banking migration with a well-defined scope, but a 12-month timeline where the startup wants the vendor to finish early and under budget.\n\n→ Use Fixed Price Incentive Fee (FPIF). Target cost agreed. If vendor beats it, both share the savings. If vendor exceeds it, both share the pain (up to the Ceiling Price).\n\nPTA Calculation (FPIF):\n\nTarget Cost = ₹80L | Target Price = ₹88L | Ceiling = ₹1.10Cr | Buyer Share = 80%\n\nPTA = ((1.10Cr − 88L) / 0.80) + 80L = (22L / 0.80) + 80L = 27.5L + 80L = ₹1.075 Cr\n\nAbove ₹1.075 Cr actual cost → vendor absorbs ALL overruns. Acts like FFP.", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Vendor Dispute — Step by Step", "Situation: A software vendor claims they delivered Phase 2 of a banking app and demands ₹45L payment. Your team says Phase 2 deliverables are incomplete — the reconciliation module is missing. The vendor says reconciliation was out of scope.\n\nWhat the PM does:\n\nStep 1 — Review the contract and SOW first (not the vendor's invoice).\n\nPull out the Statement of Work. Find the Phase 2 deliverables list. Does \"reconciliation module\" appear?\n\nStep 2 — Fact-finding with your team.\n\nAsk: Was reconciliation discussed in any email, meeting note, or change request? Is there any written record it was excluded?\n\nStep 3 — Attempt negotiation face-to-face.\n\n\"Our SOW Section 3.2 lists reconciliation as a Phase 2 deliverable. Here is the clause. Can you show me where it was excluded?\" Use data, not emotion.\n\nStep 4 — If unresolved → Claims Administration.\n\nFormally raise it as a claim. Follow the dispute resolution path in the contract: Negotiation → Mediation → Arbitration → (last resort) Litigation.\n\nStep 5 — Document everything.\n\nEvery conversation, every email, every reference to the contract clause — timestamped and filed.\n\nWhat the PM does NOT do:\n\n• Pay immediately to \"preserve the relationship\"\n\n• Terminate the contract without following the dispute process\n\n• Let legal teams fight it without PM involvement in the fact-finding", SectionKind.TIP),
                s("Worked example — 📖 Worked Example: Bidder Conference", "Project: Procuring a fraud detection AI platform for a Tier-2 bank.\n\nBefore the conference:\n\nRFP issued to 6 shortlisted vendors. Vendor 3 emails the PM privately: \"Can you clarify what 'real-time' means in your latency requirement? We need to know if What the PM does (correct):\n\nDoes NOT reply privately. Instead:\n\n1. Notes the question for the bidder conference\n\n2. At the conference, reads the question (anonymously): \"One vendor has asked what 'real-time' means — specifically whether sub-200ms latency is acceptable.\"\n\n3. PM and technical lead answer: \"Real-time means Why this matters:\n\nEvery vendor now has the same information. This is PMI Fairness — equal access to information for all qualified candidates. If Vendor 3 had received a private answer and proposed a tighter SLA, they would have an unfair competitive advantage.\n\nExam trigger: Any time a question mentions a vendor asking privately, or the PM sharing information with one vendor — the answer always involves sharing with ALL vendors or routing through the formal conference process.", SectionKind.TIP),
                s("Contract Types — Complete Risk-Allocation Framework", tableHeaders = listOf("Contract Type", "Full Name", "Buyer Pays", "Price Formula", "Cost Risk Holder", "Best Used When"), tableRows = listOf(listOf("FFP", "Firm Fixed Price", "One fixed price for all work, regardless of actual cost", "Price = Fixed amount", "SELLER bears all cost risk", "Scope is very well-defined and stable; commodity purchases; short-duration work"), listOf("FPIF", "Fixed Price Incentive Fee", "Fixed price + incentive fee based on final cost vs target", "Buyer pays Target + Fee adjustment based on (Target Cost − Actual Cost) × Seller's share ratio", "Shared risk up to ceiling price", "Scope defined but efficiency improvement is desired; want to align seller incentives with cost control"), listOf("FPEPA", "Fixed Price with Economic Price Adjustment", "Fixed price with pre-defined price adjustments for specific external factors (inflation, commodity prices)", "Price = Fixed + Adjustment index", "SELLER bears most risk; buyer absorbs defined escalation", "Long-term contracts (3+ years) where commodity or wage escalation is a real risk"), listOf("T&M", "Time and Material", "Actual hours × agreed rate + actual materials at cost", "Price = Hours × Rate + Materials", "BUYER bears most cost risk (open-ended)", "Small projects; need to start quickly before full scope known; highly skilled labour needed"), listOf("T&M with cap", "Time and Material with Not-to-Exceed", "Same as T&M but buyer defines a maximum spend", "Capped at Not-to-Exceed amount", "BUYER up to cap; then shared", "When T&M is needed but buyer wants cost certainty; protects both parties"), listOf("CPFF", "Cost Plus Fixed Fee", "All actual costs + a fixed fee that does not change", "Buyer pays AC + Fixed Fee", "BUYER bears all cost risk", "Scope highly uncertain; R&D; impossible to price risk fairly; relationship-based engagement"), listOf("CPIF", "Cost Plus Incentive Fee", "All actual costs + fee that increases when seller beats target cost", "Buyer pays AC + Fee (varies based on cost performance)", "BUYER bears more cost risk but seller incentivised to control", "Cost-uncertain scope where you still want cost efficiency incentive; long-term partnerships"), listOf("CPAF", "Cost Plus Award Fee", "All actual costs + subjective award fee based on buyer's assessment", "Buyer pays AC + Discretionary Award", "BUYER bears most cost risk", "When quality/performance dimensions are subjective; government projects where relationship quality matters"))),
                s("PTA Calculation — Point of Total Assumption", "Point of Total Assumption (FPIF only)"),
                s("Procurement Process Flow — Step by Step", tableHeaders = listOf("Phase", "Process", "Key Activities", "Key Outputs"), tableRows = listOf(listOf("Plan", "Plan Procurement Management", "Make-or-buy analysis; contract type selection; risk allocation; procurement strategy", "Procurement Management Plan, Procurement Strategy, SOW templates"), listOf("Conduct", "Conduct Procurements", "Issue procurement documents (RFP/RFQ/IFB); Bidder conferences; Proposal evaluation; Vendor selection; Contract negotiation", "Selected sellers, Agreements/Contracts, Resource calendars updates"), listOf("Control", "Control Procurements", "Contract performance monitoring; Invoice review and payment; Change request management; Quality inspections; Claims administration", "Work Performance Information, Change Requests, Updates to Project Management Plan"), listOf("Close", "Close Procurements (within Close Project or Phase in PMBOK 8)", "Final performance review; Dispute resolution; Final payment; Contract file closure; Lessons learned", "Closed contracts, Lessons Learned Register updates, OPA updates"))),
                s("Worked example — Vendor Evaluation Criteria — Weighted Scoring Example", "RFP received from 4 vendors for AI fraud detection platform:\n\n | Criterion | Weight\n | Vendor A | Vendor B | Vendor C | Vendor D\n\n | Technical approach (0–10) | 30% | 8 → 2.4 | 9 → 2.7 | 6 → 1.8 | 7 → 2.1\n\n | Price (0–10) | 25% | 7 → 1.75 | 5 → 1.25 | 9 → 2.25 | 8 → 2.0\n\n | Experience (0–10) | 20% | 9 → 1.8 | 7 → 1.4 | 5 → 1.0 | 8 → 1.6\n\n | Implementation timeline | 15% | 7 → 1.05 | 8 → 1.2 | 8 → 1.2 | 6 → 0.9\n\n | References/Financials | 10% | 8 → 0.8 | 7 → 0.7 | 6 → 0.6 | 9 → 0.9\n\n | TOTAL WEIGHTED SCORE | 100% | 7.8 | 7.25 | 6.85 | 7.5\n\nRecommendation: Vendor A (highest weighted score: 7.8)\n\nNote: Vendor C had the lowest price but ranked last overall — lowest price is NOT the selection criterion for complex solutions. The weighted scoring method makes this defensible and transparent.\n\nExam application: Any question about vendor selection → look for weighted scoring or defined evaluation criteria. Pure price selection is only for commodity purchasing (RFQ/IFB).", SectionKind.TIP),
            )
        )
    )
